include(joinpath(@__DIR__, "sabotage_run.jl"))
# ==================== validate_conv_contraction.jl =====================
# Checks the convolution twins (C3 forward, C3b adjoint): cgen_contraction_conv() = true.
#   - units of cgen_contraction_flatten (a nest of loops as one loop) and cgen_contraction_pixel (the decode of a flat index into pixel and channel)
#   - end to end on the CPU shim: a two-layer convolution (clamped window, relu) and its adjoint generated by STADE run twice from the same inputs, with the twins
#     (`contraction = 1`) and without (`contraction = 0`); the runs must agree to 1e-12, the shim must report no conflict, and some output must change
#   - SABOTAGE edits of the new code, each of which one check must catch.
#   julia validate_conv_contraction.jl        units, end to end, sabotage
isdefined(Main, :STADE) || include(joinpath(@__DIR__, "..", "src", "STADE.jl"))
isdefined(Main, :con_run) || include(joinpath(@__DIR__, "validate_contraction.jl"))
using Random

const CONV_SRC = """function cvk(img, w1, b1, w2, b2, a1, outp, n, c0, c, co)
    for i1 = 1:c * n * n
        px1 = mod(i1 - 1, n) + 1
        py1 = mod(div(i1 - 1, n), n) + 1
        oc1 = div(i1 - 1, n * n) + 1
        s1 = b1[oc1]
        for ci = 1:c0
            for ky = 1:3
                for kx = 1:3
                    yy = min(max(py1 + ky - 2, 1), n)
                    xx = min(max(px1 + kx - 2, 1), n)
                    s1 += w1[((oc1 - 1) * c0 + ci - 1) * 9 + (ky - 1) * 3 + kx] * img[((ci - 1) * n + yy - 1) * n + xx]
                end
            end
        end
        a1[i1] = max(s1, 0.0)
    end
    for i2 = 1:co * n * n
        px2 = mod(i2 - 1, n) + 1
        py2 = mod(div(i2 - 1, n), n) + 1
        oc2 = div(i2 - 1, n * n) + 1
        s2 = b2[oc2]
        for cj = 1:c
            for ky2 = 1:3
                for kx2 = 1:3
                    yy2 = min(max(py2 + ky2 - 2, 1), n)
                    xx2 = min(max(px2 + kx2 - 2, 1), n)
                    s2 += w2[((oc2 - 1) * c + cj - 1) * 9 + (ky2 - 1) * 3 + kx2] * a1[((cj - 1) * n + yy2 - 1) * n + xx2]
                end
            end
        end
        outp[i2] = max(s2, 0.0)
    end
    return nothing
end"""

# a convolution over two segments of input channels (a skip connection): the upsampled coarse tensor and the skipped one, one weight array
const SKIP_SRC = """function cvs(xa, xb, w, b, outp, n, n2, c1, c2, co)
    for i = 1:co * n * n
        px = mod(i - 1, n) + 1
        py = mod(div(i - 1, n), n) + 1
        oc = div(i - 1, n * n) + 1
        s = b[oc]
        for ci = 1:c1
            for ky = 1:3
                for kx = 1:3
                    yy = min(max(py + ky - 2, 1), n)
                    xx = min(max(px + kx - 2, 1), n)
                    s += w[((oc - 1) * (c1 + c2) + ci - 1) * 9 + (ky - 1) * 3 + kx] * xa[((ci - 1) * n2 + div(yy - 1, 2)) * n2 + div(xx - 1, 2) + 1]
                end
            end
        end
        for cj = 1:c2
            for ky2 = 1:3
                for kx2 = 1:3
                    yy2 = min(max(py + ky2 - 2, 1), n)
                    xx2 = min(max(px + kx2 - 2, 1), n)
                    s += w[((oc - 1) * (c1 + c2) + c1 + cj - 1) * 9 + (ky2 - 1) * 3 + kx2] * xb[((cj - 1) * n + yy2 - 1) * n + xx2]
                end
            end
        end
        outp[i] = max(s, 0.0)
    end
    return nothing
end"""
function skip_fargs(sd; n = 8, c1 = 3, c2 = 2, co = 5)
    r = MersenneTwister(sd)
    return Any[randn(r, c1 * (n ÷ 2)^2), randn(r, c2 * n * n), randn(r, 9 * co * (c1 + c2)), randn(r, co), zeros(co * n * n), n, n ÷ 2, c1, c2, co]
end
function skip_aargs(sd; n = 8, c1 = 3, c2 = 2, co = 5)
    r = MersenneTwister(sd); n2 = n ÷ 2
    sz = co * n * n * (4 * (c1 + c2) + 1)
    return Any[randn(r, c1 * n2 * n2), zeros(c1 * n2 * n2), randn(r, c2 * n * n), zeros(c2 * n * n), randn(r, 9 * co * (c1 + c2)), zeros(9 * co * (c1 + c2)), randn(r, co), zeros(co),
               zeros(co * n * n), randn(r, co * n * n), n, n2, c1, c2, co, zeros(sz)]
end
conv_is_twin(n) = occursin(r"_t\d*!$", n) || occursin(r"_n(16|32)_t\d*!$", n) || occursin(r"_f_t!$", n)

# the forward and the adjoint of CONV_SRC as sources, the adjoint's stacks sized for the shim
function conv_sources(; flag = true)
    Core.eval(STADE, :(cgen_contraction_conv() = $flag))
    src = Meta.parse(CONV_SRC)
    adj = STADE.stade_adjoint(src; keep_push_pop = false, fuse_ii_loops = true)
    return (fwd = CONV_SRC, adj = STADE.io_expr_to_source(adj.adjoint), adjname = Symbol(adj.adjoint.args[1].args[1]))
end
function conv_fargs(sd; n = 10, c0 = 3, c = 5, co = 4)
    r = MersenneTwister(sd)
    return Any[randn(r, c0 * n * n), randn(r, 9 * c * c0), randn(r, c), randn(r, 9 * co * c), randn(r, co), zeros(c * n * n), zeros(co * n * n), n, c0, c, co]
end
function conv_aargs(sd; n = 10, c0 = 3, c = 5, co = 4)
    r = MersenneTwister(sd)
    return Any[randn(r, c0 * n * n), zeros(c0 * n * n), randn(r, 9 * c * c0), zeros(9 * c * c0), randn(r, c), zeros(c), randn(r, 9 * co * c), zeros(9 * co * c), randn(r, co), zeros(co),
               zeros(c * n * n), zeros(c * n * n), zeros(co * n * n), randn(r, co * n * n), n, c0, c, co, zeros(c * n * n * (4c0 + 1)), zeros(co * n * n * (4c + 1))]
end

function conv_unit_checks()
    bad = 0
    check(ok, msg) = (println(rpad(ok ? "ok" : "FAIL", 6), msg); ok || (bad += 1))
    P(s) = Meta.parse(s)
    # ---- flatten
    flat(s; kw...) = STADE.cgen_contraction_flatten(P(s); kw...)
    f2 = flat("for a = 1:A\n for b = 1:B\n s = s + x[a] * y[b]\n end\nend")
    check(f2 !== nothing && occursin("__ct_kf = 1:A * B", string(f2)) && occursin("a = div(__ct_kf - 1, B) + 1", string(f2)) && occursin("b = mod(__ct_kf - 1, B) + 1", string(f2)), "flatten: two forward loops give one loop, the first slowest")
    f3 = flat("for a = 1:3\n for b = 1:3\n for c = 1:C\n s = s + x[a] * y[b]\n end\n end\nend")
    check(f3 !== nothing && occursin("1:9C", replace(string(f3), " * " => "")) || (f3 !== nothing && occursin("__ct_kf = 1:", string(f3))), "flatten: three loops give one loop")
    r2 = flat("for a = A:-1:1\n for b = B:-1:1\n s = s + x[a] * y[b]\n end\nend")
    check(r2 !== nothing && occursin("a = A - div(__ct_kf - 1, B)", string(r2)) && occursin("b = B - mod(__ct_kf - 1, B)", string(r2)), "flatten: reversed loops decode from the top")
    check(flat("for a = 1:A\n for b = B:-1:1\n s = s + x[a] * y[b]\n end\nend") === nothing, "flatten: mixed directions are refused")
    check(flat("for a = A:-1:2\n for b = B:-1:1\n s = s + x[a] * y[b]\n end\nend") === nothing, "flatten: a reversed loop that stops above 1 is refused")
    check(flat("for a = 2:A\n for b = 1:B\n s = s + x[a] * y[b]\n end\nend") === nothing, "flatten: a lower bound other than 1 is refused")
    check(flat("for a = 1:A\n for b = 1:B\n y[b] = x[a]\n end\nend") === nothing, "flatten: a body with an array store is refused")
    check(flat("for a = 1:A\n for b = 1:B\n s = s + x[a] * y[b]\n end\nend"; ok = st -> false) === nothing, "flatten: the body test decides")
    check(flat("for a = 1:A\n s += x[a]\nend") === nothing, "flatten: one loop is not a nest")
    check(flat("for a = 1:A\n t = 1.0\n for b = 1:B\n s = s + x[a] * y[b]\n end\nend") === nothing, "flatten: a statement beside the inner loop is refused")
    # ---- pixel
    stm = Any[P("px = mod(idx - 1, n) + 1"), P("py = mod(div(idx - 1, n), n) + 1"), P("oc = div(idx - 1, n * n) + 1"), P("s = 0.0")]
    out = STADE.cgen_contraction_pixel(stm, :idx, Symbol[])
    so = out === nothing ? "" : join(string.(out), "\n")
    check(out !== nothing && length(out) == 5 && occursin("__ct_pix = mod(idx - 1, n * n) + 1", so) && occursin("px = mod(__ct_pix - 1, n) + 1", so) && occursin("py = mod(div(__ct_pix - 1, n), n) + 1", so), "pixel: the decode reads one pixel column")
    check(STADE.cgen_contraction_pixel(stm[[1, 3, 4]], :idx, Symbol[]) === nothing, "pixel: a missing y decode is refused")
    check(STADE.cgen_contraction_pixel(stm[[1, 2, 4]], :idx, Symbol[]) === nothing, "pixel: a missing channel decode is refused")
    check(STADE.cgen_contraction_pixel(Any[stm[1], P("py = mod(div(idx - 1, m), n) + 1"), stm[3]], :idx, Symbol[]) === nothing, "pixel: a y decode with another width is refused")
    check(STADE.cgen_contraction_pixel(Any[stm[1], stm[2], P("oc = div(idx - 1, n * m) + 1")], :idx, Symbol[]) === nothing, "pixel: a channel decode with another stride is refused")
    check(STADE.cgen_contraction_pixel(Any[stm..., stm[1]], :idx, Symbol[]) === nothing, "pixel: two decodes of x are refused")
    return bad
end

function conv_end_checks()
    bad = 0
    check(ok, msg) = (println(rpad(ok ? "ok" : "FAIL", 6), msg); ok || (bad += 1))
    S = conv_sources(flag = true)
    for (label, kw) in (("n=10 c0=3 c=5 co=4", (;)), ("n=7 c0=2 c=9 co=3", (n = 7, c0 = 2, c = 9, co = 3)), ("n=12 c0=1 c=16 co=2", (n = 12, c0 = 1, c = 16, co = 2)))
        try
            a = con_run(S.fwd, :cvk, conv_fargs(1; kw...), 1); b = con_run(S.fwd, :cvk, conv_fargs(1; kw...), 0)
            tw = count(conv_is_twin, a.launched)
            check(con_relerr(a, b) <= 1e-12 && isempty(a.conflicts) && any(x != 0 for x in a.outs[7]), "forward $label: twins $(tw) agree with the plain kernels (error $(round(con_relerr(a, b), sigdigits = 3)))")
            a = con_run(S.adj, S.adjname, conv_aargs(2; kw...), 1; inbounds = true); b = con_run(S.adj, S.adjname, conv_aargs(2; kw...), 0; inbounds = true)
            tw = count(conv_is_twin, a.launched)
            changed = any(any(x .!= 0) for x in (a.outs[2], a.outs[4], a.outs[8]))
            check(tw >= 2 && con_relerr(a, b) <= 1e-12 && isempty(a.conflicts) && changed && count(conv_is_twin, b.launched) == 0, "adjoint $label: $(tw) twins launched, agree with the plain kernels (error $(round(con_relerr(a, b), sigdigits = 3)))")
        catch e
            check(false, "end to end $label: error " * first(split(sprint(showerror, e), "\n")))
        end
    end
    # two segments of input channels
    try
        Core.eval(STADE, :(cgen_contraction_conv() = true))
        adj = STADE.stade_adjoint(Meta.parse(SKIP_SRC); keep_push_pop = false, fuse_ii_loops = true)
        aname = Symbol(adj.adjoint.args[1].args[1]); asrc = STADE.io_expr_to_source(adj.adjoint)
        for (label, kw) in (("n=8 c1=3 c2=2 co=5", (;)), ("n=10 c1=5 c2=9 co=4", (n = 10, c1 = 5, c2 = 9, co = 4)), ("n=16 c1=16 c2=16 co=16", (n = 16, c1 = 16, c2 = 16, co = 16)))
            a = con_run(SKIP_SRC, :cvs, skip_fargs(3; kw...), 1); b = con_run(SKIP_SRC, :cvs, skip_fargs(3; kw...), 0)
            check(count(conv_is_twin, a.launched) == 1 && con_relerr(a, b) <= 1e-12 && isempty(a.conflicts) && any(x != 0 for x in a.outs[5]), "skip forward $label: one twin for the two segments, agrees with the plain kernel (error $(round(con_relerr(a, b), sigdigits = 3)))")
            a = con_run(asrc, aname, skip_aargs(4; kw...), 1; inbounds = true); b = con_run(asrc, aname, skip_aargs(4; kw...), 0; inbounds = true)
            check(count(conv_is_twin, a.launched) >= 2 && con_relerr(a, b) <= 1e-12 && isempty(a.conflicts) && any(any(x .!= 0) for x in (a.outs[2], a.outs[4], a.outs[6])), "skip adjoint $label: $(count(conv_is_twin, a.launched)) twins, agree with the plain kernels (error $(round(con_relerr(a, b), sigdigits = 3)))")
        end
    catch e
        check(false, "skip segments: error " * first(split(sprint(showerror, e), "\n")))
    end
    # the recognizer on the device kernel of the skip convolution, as written and with a change that it must refuse
    try
        Core.eval(STADE, :(cgen_contraction_conv() = true))
        plan = STADE.stade_gpu(Meta.parse(SKIP_SRC), STADE.cgen_backend_cuda(); inbounds = false, contraction = 0)
        txt = STADE.io_expr_to_source(plan.kernels[1])
        sec = "s = s + w[(((oc - 1) * (c1 + c2) + c1 + cj)"
        variants = (("as written", txt, true),
                    ("the second nest adds into another sum", replace(replace(replace(txt, sec => "t = t + w[(((oc - 1) * (c1 + c2) + c1 + cj)"), "s = b[oc]" => "s = b[oc]\n    t = 0.0"), "outp[i] = max(s, 0.0)" => "outp[i] = max(s + t, 0.0)"), false),
                    ("an array of the second segment is stored", replace(txt, "outp[i] = max(s, 0.0)" => "outp[i] = max(s, 0.0)\n    xb[i] = 1.0"), false),
                    ("the weight array is stored", replace(txt, "outp[i] = max(s, 0.0)" => "outp[i] = max(s, 0.0)\n    w[i] = 1.0"), false))
        for (label, src, must) in variants
            r = try STADE.cgen_contraction_kernel(Meta.parse(src); cmin = 1) catch e; e end
            check(must ? r isa NamedTuple : r === nothing, "skip recognizer, $label: " * (must ? "a twin is built" : "refused"))
        end
    catch e
        check(false, "skip recognizer: error " * first(split(sprint(showerror, e), "\n")))
    end
    # the kernels without the software pipeline
    try
        Core.eval(STADE, :(cgen_contraction_prefetch() = false))
        a = con_run(S.fwd, :cvk, conv_fargs(1), 1); b = con_run(S.fwd, :cvk, conv_fargs(1), 0)
        check(count(conv_is_twin, a.launched) == 2 && con_relerr(a, b) <= 1e-12 && isempty(a.conflicts), "no prefetch: forward twins agree (error $(round(con_relerr(a, b), sigdigits = 3)))")
        a = con_run(S.adj, S.adjname, conv_aargs(2), 1; inbounds = true); b = con_run(S.adj, S.adjname, conv_aargs(2), 0; inbounds = true)
        check(count(conv_is_twin, a.launched) >= 2 && con_relerr(a, b) <= 1e-12 && isempty(a.conflicts), "no prefetch: adjoint twins agree (error $(round(con_relerr(a, b), sigdigits = 3)))")
    catch e
        check(false, "no prefetch: error " * first(split(sprint(showerror, e), "\n")))
    end
    Core.eval(STADE, :(cgen_contraction_prefetch() = true))
    # the flag off: no conv twin, the same plan text as contraction = 0
    try
        Core.eval(STADE, :(cgen_contraction_conv() = false))
        T = conv_sources(flag = false)
        a = con_run(T.adj, T.adjname, conv_aargs(2), 1; inbounds = true); b = con_run(T.adj, T.adjname, conv_aargs(2), 0; inbounds = true)
        check(count(conv_is_twin, a.launched) == 0 && con_relerr(a, b) == 0.0, "flag off: no conv twin is launched")
    catch e
        check(false, "flag off: error " * first(split(sprint(showerror, e), "\n")))
    end
    Core.eval(STADE, :(cgen_contraction_conv() = true))
    return bad
end

function validate_conv_contraction(; phases = (:units, :end, :sabotage), slice = 1:typemax(Int))
    bad = 0
    :units in phases && (println("-- units"); bad += conv_unit_checks())
    :end in phases && (println("-- end to end"); bad += conv_end_checks())
    if :sabotage in phases
        println("-- sabotage")
        check(ok, msg) = (println(rpad(ok ? "ok" : "FAIL", 6), msg); ok || (bad += 1))
        text = read(joinpath(abspath(joinpath(@__DIR__, "..")), "src", "STADE.jl"), String)
        cases = [
            ("loops of both directions may be flattened", "    any(l -> l.rev, loops) && !all(l -> l.rev, loops) && return nothing\n", ""),
            ("the body of a flattened nest is not tested", "    all(ok, body) || return nothing\n", ""),
            ("a reversed loop decodes as a forward one", "loops[j].rev ? Expr(:call, :-, loops[j].hi, q) : Expr(:call, :+, q, 1)", "Expr(:call, :+, q, 1)"),
            ("an inner loop decodes without the modulus", "        j > 1 && (q = Expr(:call, :mod, q, loops[j].hi))\n", ""),
            ("a reversed loop may stop above 1", "length(rng.args) == 4 && rng.args[3] == -1 && rng.args[4] == 1", "length(rng.args) == 4 && rng.args[3] == -1"),
            ("a forward loop may start above 1", "if length(rng.args) == 3 && rng.args[2] == 1\n", "if length(rng.args) == 3\n"),
            ("the y decode may use another width", "    stmts[py[1]].args[2].args[2].args[2].args[3] == a || return nothing\n", ""),
            ("the channel decode may use another stride", "r.args[3] == nab && push!(oc, i)", "push!(oc, i)"),
            ("the channel decode is not required", "    length(oc) == 1 || return nothing\n", ""),
            ("the x and y decodes need not be unique", "(length(px) == 1 && length(py) == 1 && a !== nothing && b !== nothing)", "(a !== nothing && b !== nothing)"),
            ("the second segment reads from the first offset", "cadd(d.kbase, starts[i] === 0 ? kg : call(:-, kg, starts[i]))", "cadd(d.kbase, kg)"),
            ("the total inner length leaves out the second segment", "    for sg in segs\n        K = Expr(:call, :+, K, sg.lp.hi)\n    end\n", ""),
            ("the second nest may add into another sum", "sj[1][1] === sums[1][1] && sj[1][2] === sums[1][2] && ", ""),
            ("the segment boundary is not tested", "Expr(:if, call(:<, kg, ends[i]), blk, chain)", "Expr(:if, call(:<, kg, 0), blk, chain)"),
            ("a second-segment array that is stored is accepted", "; union!(opsyms, extra_ops)", ""),
            ("the prefetch reads the current tile", "asg(:__ct_kn, cadd(:__ct_k0, TK))", "asg(:__ct_kn, :__ct_k0)"),
            ("the first tile is not read before the loop", "        append!(body, ldA); append!(body, ldB)\n", ""),
            ("no barrier after the stores", "stA..., stB..., call(:sync_threads), asg(:__ct_kn", "stA..., stB..., asg(:__ct_kn"),
            ("the first prefetch of a split sum starts at zero", "push!(body, asg(:__ct_kn, splitk ? cmul(:__ct_z, :__ct_kc) : 0))", "push!(body, asg(:__ct_kn, 0))"),
            ("the pixel is not reduced modulo the plane", "Expr(:(=), :__ct_pix, Expr(:call, :+, Expr(:call, :mod, X, nab), 1))", "Expr(:(=), :__ct_pix, Expr(:call, :+, X, 1))"),
        ]
        mktempdir() do tmp
            for (label, old, new) in cases[intersect(eachindex(cases), slice)]
                n = length(findall(old, text))
                if n != 1
                    check(false, "sabotage \"$label\": anchor found $n times")
                    continue
                end
                get(ENV, "SAB_ANCHORS_ONLY", "") == "1" && (check(true, "anchor \"$label\": found once"); continue)
                path = joinpath(tmp, "STADE_sab.jl")
                write(path, replace(text, old => new; count = 1))
                script = """
                    include($(repr(path)))
                    cd($(repr(@__DIR__)))
                    include($(repr(joinpath(@__DIR__, "validate_conv_contraction.jl"))))
                    n = sab_phase_sum($(repr("validate_conv_contraction.jl")), $(repr(label)), [conv_unit_checks, conv_end_checks])
                    println("RESULT ", n)
                """
                out = sab_read(script)
                m = match(r"RESULT (\d+)", out)
                caught = out == "ERR" || m === nothing || parse(Int, m.captures[1]) > 0
                check(caught, "sabotage \"$label\": " * (caught ? "a check fails" : "NOT CAUGHT"))
            end
        end
    end
    println("\n", bad == 0 ? "all conv contraction checks passed" : "*** $bad conv contraction check(s) failed ***")
    return bad
end
abspath(PROGRAM_FILE) == abspath(joinpath(@__DIR__, "validate_conv_contraction.jl")) && validate_conv_contraction(; phases = (:units, :end, :sabotage))
